insert into public.reading_texts (code, cefr, text_type, situation, module_order, title_ua, title_hr, body_hr, body_ua, glossary, questions, word_count, known_ratio, order_index, status, source)
values ('RD-A2-004', 'A2', 'story', 'travel', 2, 'Поїздка до Дубровника', 'Izlet u Dubrovnik',
        'Prošlog ljeta Andrij i njegova sestra putovali su u Dubrovnik. Iz Zagreba su išli autobusom, a put je trajao skoro deset sati. Bili su umorni, ali grad ih je oduševio. Prvi dan šetali su po gradskim zidinama i gledali more i crvene krovove. Drugi dan otišli su brodom na otok Lokrum. Tamo su se kupali i jeli sladoled. Navečer su probali ribu u malom restoranu u Starom gradu. Bilo je skupo, ali jako ukusno. Sestra je napravila sto fotografija. Andrij kaže da će se sigurno vratiti, ali sljedeći put putovat će avionom.',
        'Минулого літа Андрій і його сестра їздили до Дубровника. Із Загреба вони їхали автобусом, і дорога тривала майже десять годин. Вони були втомлені, але місто їх зачарувало. Першого дня вони гуляли міськими мурами й дивилися на море та червоні дахи. Другого дня вони попливли кораблем на острів Локрум. Там вони купалися й їли морозиво. Увечері вони скуштували рибу в маленькому ресторані в Старому місті. Було дорого, але дуже смачно. Сестра зробила сто фотографій. Андрій каже, що неодмінно повернеться, але наступного разу полетить літаком.',
        '[{"form": "prošlog", "lemma": "prošli", "ua": "минулий", "lesson": false, "pos": "прикметник «минулий»", "gram": "родовий відмінок (кого? чого?), однина, с. р. «prošlog ljeta» — минулого літа"}, {"form": "ljeta", "lemma": "ljeto", "ua": "літо", "lesson": true, "pos": "іменник, середній рід", "gram": "родовий відмінок (кого? чого?), однина"}, {"form": "andrij", "lemma": "Andrij", "ua": "Андрій (ім’я)", "lesson": false, "pos": "ім’я (чоловіче)"}, {"form": "i", "lemma": "i", "ua": "і; та", "lesson": false, "pos": "сполучник"}, {"form": "njegova", "lemma": "njegov", "ua": "його (присвійний)", "lesson": false, "pos": "присвійний займенник «його»", "gram": "називний відмінок (хто? що?), однина, ж. р."}, {"form": "sestra", "lemma": "sestra", "ua": "сестра", "lesson": true, "pos": "іменник, жіночий рід"}, {"form": "putovali", "lemma": "putovati", "ua": "подорожувати, їхати", "lesson": true, "pos": "дієслово, недоконаний вид (що робити?)", "gram": "минулий час (форма на -l): ч. р., множина"}, {"form": "su", "lemma": "biti", "ua": "бути; є", "lesson": false, "pos": "дієслово «бути» (недоконаний вид); короткі форми sam, si, je, smo, ste, su", "gram": "теперішній час: вони"}, {"form": "u", "lemma": "u", "ua": "у; в", "lesson": false, "pos": "прийменник: + знахідний — куди? («u školu»), + місцевий — де? («u Zagrebu»)"}, {"form": "dubrovnik", "lemma": "Dubrovnik", "ua": "Дубровник (місто)", "lesson": false, "pos": "назва місця"}, {"form": "iz", "lemma": "iz", "ua": "з (звідки)", "lesson": false, "pos": "прийменник + родовий відмінок"}, {"form": "zagreba", "lemma": "Zagreb", "ua": "Загреб", "lesson": false, "pos": "назва місця", "gram": "родовий відмінок (кого? чого?), однина"}, {"form": "išli", "lemma": "ići", "ua": "іти, їхати", "lesson": true, "pos": "дієслово, недоконаний вид (що робити?)", "gram": "минулий час (форма на -l): ч. р., множина"}, {"form": "autobusom", "lemma": "autobus", "ua": "автобус", "lesson": true, "pos": "іменник, чоловічий рід", "gram": "орудний в