insert into public.reading_texts (code, cefr, text_type, situation, module_order, title_ua, title_hr, body_hr, body_ua, glossary, questions, word_count, known_ratio, order_index, status, source)
values ('RD-A2-005', 'A2', 'story', 'work', 3, 'Перший тиждень на новій роботі', 'Prvi tjedan na novom poslu',
        'Danilo je prošli tjedan počeo raditi u velikom skladištu blizu Zagreba. Prvi dan mu je voditelj pokazao cijelo skladište i objasnio pravila. Radno vrijeme je od šest do dva, pa Danilo mora ustati u pet. Prva dva dana bila su teška: nije razumio sve što su kolege govorili, a bilo ga je sram pitati. Treći dan jedan kolega, Marko, ponudio mu je pomoć. Sada mu Marko polako objašnjava riječi koje ne zna. Danilo je zadovoljan: plaća je dobra, a kolege su ljubazni. Sljedeći mjesec dobit će ugovor na godinu dana.',
        'Минулого тижня Данило почав працювати на великому складі біля Загреба. Першого дня керівник показав йому весь склад і пояснив правила. Робочий час — із шостої до другої, тому Данило мусить вставати о п’ятій. Перші два дні були важкими: він не розумів усього, що говорили колеги, а питати соромився. Третього дня один колега, Марко, запропонував йому допомогу. Тепер Марко повільно пояснює йому слова, яких він не знає. Данило задоволений: зарплата хороша, а колеги привітні. Наступного місяця він отримає договір на рік.',
        '[{"form": "danilo", "lemma": "Danilo", "ua": "Данило (ім’я)", "lesson": false, "pos": "ім’я (чоловіче)"}, {"form": "je", "lemma": "biti", "ua": "бути; є", "lesson": false, "pos": "дієслово «бути» (недоконаний вид); короткі форми sam, si, je, smo, ste, su", "gram": "теперішній час: він / вона / воно. Коротка форма"}, {"form": "prošli", "lemma": "prošli", "ua": "минулий", "lesson": false, "pos": "прикметник «минулий»"}, {"form": "tjedan", "lemma": "tjedan", "ua": "тиждень", "lesson": true, "pos": "іменник, чоловічий рід"}, {"form": "počeo", "lemma": "početi", "ua": "почати", "lesson": true, "pos": "дієслово, доконаний вид (що зробити?)", "gram": "минулий час (форма на -l): ч. р., однина"}, {"form": "raditi", "lemma": "raditi", "ua": "працювати, робити", "lesson": true, "pos": "дієслово, недоконаний вид (що робити?)"}, {"form": "u", "lemma": "u", "ua": "у; в", "lesson": false, "pos": "прийменник: + знахідний — куди? («u školu»), + місцевий — де? («u Zagrebu»)"}, {"form": "velikom", "lemma": "velik", "ua": "великий", "lesson": true, "pos": "прикметник", "gram": "місцевий відмінок (де? про кого? про що?), однина, с. р."}, {"form": "skladištu", "lemma": "skladište", "ua": "склад", "lesson": true, "pos": "іменник, середній рід", "gram": "місцевий відмінок (де? про кого? про що?), однина"}, {"form": "blizu", "lemma": "blizu", "ua": "поруч / близько", "lesson": true, "pos": "прислівник «близько»; як прийменник — + родовий («blizu tramvaja»)"}, {"form": "zagreba", "lemma": "Zagreb", "ua": "Загреб", "lesson": false, "pos": "назва місця", "gram": "родовий відмінок (кого? чого?), однина"}, {"form": "prvi", "lemma": "prvi", "ua": "перший", "lesson": true, "pos": "порядковий числівник"}, {"form": "dan", "lemma": "dan", "ua": "день", "lesson": false, "pos": "іменник, чоловічий рід"}, {"form": "mu", "lemma": "on", "ua": "він", "lesson": false, "pos": "особовий займенник «він»", "gram": "давальний відмінок (кому? чому?), однина. «pokazao mu je» — показав йому"}, {"form": "vo