values ('RD-A2-006', 'A2', 'email', 'work', 3, 'Прохання про відпустку', 'Molba za godišnji odmor',
        'Poštovana gospođo Babić,
htio bih uzeti godišnji odmor od 4. do 15. kolovoza. U to vrijeme moja obitelj dolazi iz Ukrajine i želio bih provesti nekoliko dana s njima. Razgovarao sam s kolegom Jurićem i on me može zamijeniti na smjenama. Sve zadatke završit ću do kraja srpnja. Ako taj termin nije moguć, molim vas da mi predložite drugi.
Hvala na razumijevanju.
S poštovanjem,
Taras Kovalenko',
        'Шановна пані Бабич!
Я хотів би взяти відпустку з 4 по 15 серпня. У цей час до мене приїжджає родина з України, і я хотів би провести з ними кілька днів. Я поговорив із колегою Юричем, і він може замінити мене на змінах. Усі завдання я закінчу до кінця липня. Якщо ці дати неможливі, прошу запропонувати мені інші.
Дякую за розуміння.
З повагою,
Тарас Коваленко',
        '[{"form": "poštovana", "lemma": "poštovani", "ua": "шановний", "lesson": false, "pos": "прикметник «шановний» (звертання в листі)", "gram": "називний відмінок (хто? що?), однина, ж. р. Звертання до жінки в листі"}, {"form": "gospođo", "lemma": "gospođa", "ua": "пані", "lesson": true, "pos": "іменник, жіночий рід", "gram": "кличний відмінок (звертання), однина"}, {"form": "babić", "lemma": "Babić", "ua": "Бабич (прізвище)", "lesson": false, "pos": "прізвище"}, {"form": "htio", "lemma": "htjeti", "ua": "хотіти", "lesson": true, "pos": "дієслово «хотіти» (недоконаний вид); короткі форми ću, ćeš… — для майбутнього часу", "gram": "минулий час (форма на -l): ч. р., однина. «htio bih» — я хотів би"}, {"form": "bih", "lemma": "biti", "ua": "бути; є", "lesson": false, "pos": "дієслово «бути» (недоконаний вид); короткі форми sam, si, je, smo, ste, su", "gram": "умовний спосіб: я («htio bih / htjela bih» — я хотів би / хотіла б)"}, {"form": "uzeti", "lemma": "uzeti", "ua": "взяти", "lesson": true, "pos": "дієслово, доконаний вид (що зробити?)"}, {"form": "godišnji", "lemma": "godišnji odmor", "ua": "щорічна відпустка", "lesson": true, "pos": "сталий вираз", "gram": "знахідний відмінок (кого? що?), однина, ч. р. Частина виразу «godišnji odmor»"}, {"form": "odmor", "lemma": "godišnji odmor", "ua": "щорічна відпустка", "lesson": true, "pos": "сталий вираз", "gram": "знахідний відмінок (кого? що?), однина. «godišnji odmor» — щорічна відпустка"}, {"form": "od", "lemma": "od", "ua": "від; з", "lesson": false, "pos": "прийменник + родовий відмінок"}, {"form": "do", "lemma": "do", "ua": "до", "lesson": false, "pos": "прийменник + родовий відмінок"}, {"form": "kolovoza", "lemma": "kolovoz", "ua": "серпень", "lesson": true, "pos": "іменник, чоловічий рід", "gram": "родовий відмінок (кого? чого?), однина"}, {"form": "u", "lemma": "u", "ua": "у; в", "lesson": false, "pos": "прийменник: + знахідний — куди? («u školu»), + місцевий — де? («u Zagrebu»)"}, {"form": "to", "lemma": "to"