-- Журнал перевірки (один запис на текст)
insert into public.content_reviews (entity_type, entity_id, from_status, to_status, verdict, reviewer_kind, findings, notes)
select 'reading_text', r.id, null, r.status, 'auto_passed', 'ai', '[]'::jsonb, 'Тексти для читання A2 (§6) за запитом власника 2026-10-15 (reading_a2_v1). DRAFT: публікує власник після перевірки.'
from public.reading_texts r
where r.source = 'claude_reading_a2_v1' and r.code in ('RD-A2-001', 'RD-A2-002', 'RD-A2-003', 'RD-A2-004', 'RD-A2-005', 'RD-A2-006', 'RD-A2-007', 'RD-A2-008', 'RD-A2-009', 'RD-A2-010')
  and not exists (select 1 from public.content_reviews c where c.entity_id = r.id and c.notes = 'Тексти для читання A2 (§6) за запитом власника 2026-10-15 (reading_a2_v1). DRAFT: публікує власник після перевірки.');

-- Самоперевірка: якщо щось не так — усе відкочується
do $$
declare v_total int; v_bad int;
begin
  select count(*) into v_total from public.reading_texts where source = 'claude_reading_a2_v1' and code in ('RD-A2-001', 'RD-A2-002', 'RD-A2-003', 'RD-A2-004', 'RD-A2-005', 'RD-A2-006', 'RD-A2-007', 'RD-A2-008', 'RD-A2-009', 'RD-A2-010');
  select count(*) into v_bad from public.reading_texts r where r.source = 'claude_reading_a2_v1' and r.code in ('RD-A2-001', 'RD-A2-002', 'RD-A2-003', 'RD-A2-004', 'RD-A2-005', 'RD-A2-006', 'RD-A2-007', 'RD-A2-008', 'RD-A2-009', 'RD-A2-010')
     and (jsonb_array_length(r.questions) <> 3 or r.known_ratio < 0.7
          or exists (select 1 from jsonb_array_elements(r.glossary) e
                     where e->>'pos' is null or (e->>'gram' is null and e->>'form' <> lower(e->>'lemma'))));
  if v_total < 10 then raise exception 'Текстів %, очікувалось 10', v_total; end if;
  if v_bad > 0 then raise exception '% текстів без питань, словничка чи граматичних підказок', v_bad; end if;
  raise notice 'Готово: текстів для читання A2 · частина 1 з 2 — %', v_total;
end $$;

commit;
